import math
from fractions import Fraction

def recover(m, t, a, n):
    r = Fraction(m, 2 ** t).limit_denominator(n).denominator
    if pow(a, r, n) != 1 or r % 2 or pow(a, r // 2, n) == n - 1:
        return None
    f = math.gcd(pow(a, r // 2, n) - 1, n)
    return (f, n // f)

print(recover(192, 8, 7, 15))

