import json, struct

def encode(header, *blobs):
    h = dict(header, v=2, lens=[len(b) for b in blobs])
    raw = json.dumps(h, separators=(",", ":"), sort_keys=True).encode()
    return struct.pack(">H", len(raw)) + raw + b"".join(blobs)

